INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1131439', 'stk-fin_analyst', 'ACCT 210', 'info', '{"desc": "الآن اسمها Acct210\n\nوهذي معلومات عن الكورس من الـ syllabus\n\nCOURSE DESCRIPTION\n\nThis Course covers uses of accounting information for managerial decision making to aid planning\nand control activities of managers in business enterprises. Topics include methods for determining the\ncosts of products and services, cost behavior analysis, assessing product and project profitability, cost-volume-profit analysis, budgeting, cost control using standard costing and variance analysis…\n\nCOURSE OUTCOMES\n\nOn successful completion of the course, students should be able to (needs updating):\n· Understand managerial accounting related to the processing, preparation, and use of accounting information by organizations for planning, control and decision-making.\n· Differentiate between situations requiring internal or external use of accounting information and to be able to advice or act accordingly.\n· Acquire basic skills necessary to determine product and service costs.\n· Recognize and analyze cost behavior and cost-volume-profit relationships.\n· Understand the role of operating budgets in planning and decision making.\n· Acquire skills necessary to read, interpret and perform the calculations for the accounting reports involved in cost control and profit planning.\n· Appreciate the behavioral and ethical issues faced by management accountants\n\nطريقة توزيع الدرجات والاختبارات والهوموركات الاونلاين كلها نفس acct201 اللي هي acct110 الآن\n\nبرأيي الكورس اسهل شوي من الكورس اللي قبله ، لكن بالتاكيد يحتاج متابعة وحل تمارين\n\n----\n\nمادري اذا غطيت المعلومات اللي تبغاها ، اذا عندك اي اسألة لا تترد 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct-210-introduction-to-managerial-accounting/120957/5", "user": "FIN_Analyst", "ts": 1354639709000, "tid": 120957, "pn": 5}}', 1354639709000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1324129', 'stk-hussain07', 'ACCT 210', 'info', '{"desc": "الكتاب الظاهر تم تغييره\n\nاسمه الان\n\nManagerial Accounting Braun and tietz 3rd Edition\n\nيا ليت احد يجيب لنا ال Solutions Manual", "type": "", "rel": 0, "lang": "", "book": "Managerial Accounting Braun and tietz 3rd Edition", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct-210-introduction-to-managerial-accounting/120957/8", "user": "Hussain07", "ts": 1391004586000, "tid": 120957, "pn": 8}}', 1391004586000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1348210', 'stk-practice', 'ACCT 210', 'info', '{"desc": "Term 141\n\n1- اخف من Acct110\n2- فيها جزء متعلق بـ Fin250 اللي هوا Financial Statements Analysis\n3- دكاترة المادة شرحهم مو ذاك الشي ولكن الكتب كويس ويغنيك عنهم\n4- ماتيريال المادة يعتبر طويل لو اعتبرته نظري ، لكن التركيز بالمياجر على المسائل اكثر شي وهذه ميزة\n5- اسئلة المياجر شبيهة باسئلة السيلابس واسئلة الاختيارات بنهاية كل شابتر\n6- الكلام عن الكورس هذا كثير ولكن فيه طلاب يجيبو A ، تقدر تكون واحد منهم اذا اهتميت\n\nموفقين", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct-210-introduction-to-managerial-accounting/120957/9", "user": "Practice", "ts": 1396596152000, "tid": 120957, "pn": 9}}', 1396596152000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1423125', 'stk-user10207', 'ACCT 210', 'info', '{"desc": "- أخذت المادة بترم 142\n- المادة أشوفها متوسطة ليست صعبة وليست سهلة.\n- المادة فيها حسابات وقوانين كثير. بعض الأسئلة تأخذ وقت طويل.\n- الكتاب جيد. مع نهاية كل شبتر فيه حوالي 50 إلى 60 سؤال. إذا حليتهم كلهم ممتاز.\n- ركز على أسئلة البراكتس الي بالسلبس لأنها تجي نفسها بالميجر.\n- الهوموركات أونلاين. نفس أسئلة الكتاب بالضبط.\n- الكورس يبدأ معك سهل بعدين يصعب كل ما اخذت شبتر جديد.\n- أنصح في هذا الكورس بالدكتور حيدر مدني، لأنه هو الكورنديتور.\n- نظام المياجر للأسف مااعجبني. مش مثل acct 110.\n- الميجر والفاينل يجيك مثلا 3 مسائل فقط وكل واحدة عليها 20% أو 30%\n- إذا ماعرفت تحل المسألة، بتروح عليك بوينتس كثير.\n- القريدات في هذا الكورس ماكانت مرضية.\n- أول ميجر سهل لازم تجيب فيه درجة كويسة. نفس الشيء ميجر 2 متوسط مائل للسهل.\n- المشكلة هي الفاينل. الماتيريال نفسه طويل وأصعب شوي من الشباتر الي قبل.\n- المادة مش كومبرهنسف. الفاينل 4 شباتر فقط لكنها طويلة.\n- قبل المياجر والفاينل، فيه كلاس في الليل تحل فيه تمارين وفيه بونص. الحضور مش إجباري.\n- طبعاً الكلاس المراجعة الي بالليل يحل المسائل نفسها الي بتجي في الميجر والفاينل!\n- فيه مشكلة في الكورس دائماً تتكرر. موعد ميجر 2 يكون في آخر الأسابيع وبينه وبين الفاينل فقط اسبوعين!\n- نفس الشيء الميجر الأول يكون في نهاية الإسبوع الثامن. مواعيد المياجر جداً سيئة.\n- إذا تبي قريد ممتاز. كل الي عليك أنك تبدع في ميجر 1، و 2 وتحل الهوموركات، وتحل اسئلة البراكتس الي بالسلبس.\n- الكتاب لاتقرأه قبل الميجر، خل تركيزك على المسائل فقط. القراءة فقط تكون في الأيام العادية.\n- فيه اسئلة ملتبل شويز بعد نهاية كل شبتر، يجيبون منها كثير في الميجر والفاينل.\n- الكورس هذا مهم إذا تبي تفهم أكثر fin 250.\n- بالتوفيق إن شاء الله.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct-210-introduction-to-managerial-accounting/120957/11", "user": "user10207", "ts": 1438172001000, "tid": 120957, "pn": 11}}', 1438172001000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1475976', 'stk-user9840', 'ACCT 210', 'info', '{"desc": "Term 162\n\nالكورس ما اشوفه بصعوبة 110 ، لكن الدكاترة متمثلين في مدني والحربي يخلونك تكره الكورس لكن بشكل عام كورس جيد خصوصا ان من ترم 171 راح يدرس هالكورس ميرغني فراح يصير الكورس خفيف .\n\n-اقرا الكتاب وفهمه وحل اسئلة السيلابوس والهومورك بنفسك وراح تطلع بقريد بطل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct-210-introduction-to-managerial-accounting/120957/12", "user": "user9840", "ts": 1499306504000, "tid": 120957, "pn": 12}}', 1499306504000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1525351', 'stk-nawafmkz', 'ACCT 210', 'info', '{"desc": "ACCT 210 Introduction to Managerial Accounting\n192\nمادة متوسطة ومقدور عليها بالمذاكرة، أسهل من 110 حسب تجربتي.\nأفضل طريقة للمذاكرة الكتاب + الاونلاين هوموورك + الهانداوت. هذي كافية ووافية للفهم والاستعداد للاختبارات.\nالكتاب ممتاز جدا وسهل ويشرح بالتدريج، حتى لو دكتورك سيء المادة سهلة كself study.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct-210-introduction-to-managerial-accounting/120957/13", "user": "NawafMKZ", "ts": 1599247982000, "tid": 120957, "pn": 13}}', 1599247982000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p847675', 'stk-3thmanol', 'ACCT 210', 'info', '{"desc": "السلام عليكم يا شباب … كيف حالكم ؟!\nأبي أشوف أرآئكم عن فاينل الاكاونتنق … الصراح في نظري انا كان صعب حبتين …\nوكين فيه تريك في اغلب الاسئله …\nيعني انا ذاكرت الاسئله والبروبلمز اللي الدكتور عطانا اياها كلها … مع ذلك واجهة في اسئله كثيره صعوبه ونكبات !\n\nوش رايكم انتم ؟", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/107923/1", "user": "3thmanol", "ts": 1307401671000, "tid": 107923, "pn": 1}}', 1307401671000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p956717', 'stk-9ami', 'ACCT 210', 'info', '{"desc": "المادة تحتاج لمتابعة وحل مسائل كثيير وحاول ما يفوتك شي لأن الدروس مترابطة\n\nترى الكتاب مناسب جدا للمذاكرة ولكن حلك للمسائل يرسخ الفكرة في مخك 🤴\n\nنصيحة من أخ يدرس حالياً اكاونتنج 202 … أساسك في المادة 201 راح يساعدك في الـ 202", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct-202/114257/10", "user": "9ami", "ts": 1325394849000, "tid": 114257, "pn": 10}}', 1325394849000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p101403', 'stk-user607', 'ACCT 210', 'info', '{"desc": "acct202 : مادة المفروض إنها سهل من ACCT 201 إذا فهمتها وخذها مع أبو موسى وبس", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/50950/2", "user": "user607", "ts": 1150640199000, "tid": 50950, "pn": 2}}', 1150640199000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p610040', 'stk-the_don', 'ACCT 210', 'info', '{"desc": "Acct 202 … ماده تقدر تعتمد فيها على نفسك بالمذاكره\nماده دسمه حبتين …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/214-202-202-211-pe/88402/10", "user": "The_Don", "ts": 1274189747000, "tid": 88402, "pn": 10}}', 1274189747000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p923939', 'stk-9ami', 'ACCT 210', 'srcU', '{"html": "وعليكم السلام ورحمة الله وبركاته<br><br>شوف أخوي بأقولك من الآخر , ما تحتاج مدرس خصوصي !<br><br>ادخل على wiley plus طبعا راح تحصل التوتوريال لكل شابتر , أبدأ من شابتر 1 إلى 4 أوكي !!<br><br>وحل كمـ سؤال من كل شابتر وتأكد بأنك ما تخلص الشابتر إلا وأنت فاهمـ<br><br>وبعدين ذاكر شابتر 12 - 16 وأمورك في السليمـ , حل مسائل حتى ترسخ الفكرة في مخك<br><br>أعيد وأكرر , ما تحتاج مدرس خصوصي !!!", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct-202/114257/6", "user": "9ami", "ts": 1319334431000, "tid": 114257, "pn": 6}}', 1319334431000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p923974', 'stk-anoosh', 'ACCT 210', 'srcU', '{"html": "الكتاب + الـwiley plus تغنيك عن مدرس خصوصي<br><br>اهم شي تقرأ و تحل تمارين كثير … موفق 🌺", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct-202/114257/7", "user": "Anoosh", "ts": 1319344970000, "tid": 114257, "pn": 7}}', 1319344970000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p924493', 'stk-user8337', 'ACCT 210', 'srcU', '{"html": "روق ترويقة محترمه … ثم اقرأ إقرا إقرا … أسلوب الكتاب يفهمك كل شي لذالك هو كبير وتحس انه غثيث لكن فقط اقرأ وفي بالك انك تبي تحصل على المعلومة وانس من حجم الكتاب بتلاقي نفسك تفهم . صدقني جرب…", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct-202/114257/8", "user": "user8337", "ts": 1319400569000, "tid": 114257, "pn": 8}}', 1319400569000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1315794', 'stk-fin_analyst', 'ACCT 210', 'srcU', '{"html": "امم …ماراح تحتاج ترجع لاشياء كثيرة …<br><br>مبادئ المبادئ … يعني لازم تعرف ايش هي الـ income-statement and balance sheet<br>ومكونات كل وحده فيهم<br><br>اغلب الكورس حيتكلم عن الـ costing والـ cost of goods sold وشوية budgeting<br><br>كيف تحسب التكلفة وكذا والمخزون وهذي الاشياء … يعني الكورسين مختلفة تقريبا<br><br>في شابتر financial statement analysis يمكن هوا اكثر شابتر يعتمد على اللي القبل…ولو موارتباط مباشر بس عشان تفهمه مزبوط لازم تكون فاهم الاسياسيات ومكونات القوائم المالية وايش تعني كل وحدة فيهم", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct210/154985/2", "user": "FIN_Analyst", "ts": 1388975190000, "tid": 154985, "pn": 2}}', 1388975190000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1470382', 'stk-hard-worker', 'ACCT 210', 'srcU', '{"html": "الكورس بصفة عامه يعتبر ثقيل هو و acct110 لكن طريقتي بالمذاكرة كانت معتمده ع السلايدات عشان افهم الشابتر بصفة عامه وبعدها اخذ recommended problems من السيلابوس وأحلها واسئلة ال online homework … لو تذاكر المصادر الثلاثة ذي تعتبر جدا كافية انك تجيب +80<br>… الله يوفقك بالميجر الجاي وحاول تعتمد هذي المصادر بس تبدأ من بدري عشان تفهمها صح", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct210/176349/2", "user": "HARD-WORKER", "ts": 1490300384000, "tid": 176349, "pn": 2}}', 1490300384000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1443253', 'stk-practice', 'ACCT 210', 'srcP', '{"html": "للاسف ما بتلقى لها الا سلوشن مانوال<br><br>عالعموم مسائل الاختبار تتشبه Practice Problems اللي بالسيلابس - والـMCQ تتكرر من الاسئلة اللي بنهاية كل شابتر<br>موفق", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct210/172455/2", "user": "Practice", "ts": 1456525600000, "tid": 172455, "pn": 2}}', 1456525600000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p630163', 'stk-user5961', 'ACCT 210', 'srcP', '{"html": "السلام عليكم<br><br>هذي اخوي الكوفر بيج حقت الفاينل وفيها عناوين الأسئلة الي بتجي ,<br><br>بتفيدكم<br><br>ودعواتكم ,<br><br>​<span data-fid=\"stk-f630163-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f630163-0": {"name": "final acc.pdf", "v": "data:application/pdf;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/accounting-202/89593/3", "user": "user5961", "ts": 1276395054000, "tid": 89593, "pn": 3}}', 1276395054000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-practice-acct210', 'stk-practice', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-madani", "n": "Dr. Haider Husain Madani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "تقييمي عنه بنهاية الترم\n\nacct210 - 141\n\n- مافي شرح , يمكن تستفيد 10% او اقل\n- يطلب منك تطلع 6 مرات تحل اسئلة هو مختارها *مو السؤال كامل , بارت منه والباقي طالب غيرك* هيا نفس\nالاسئلة اللي تجي في الميجر مع تغيير الارقام واحيانا اقصر مو السؤال كامل\n- ثلاثة كويزات اونلاين , واحد منهم اختياري\n- بونس 1% للي ما عنده ولا غياب\n- يسمح بالميك اب\n- مافي شي اسمو ليت , لو تحضر اخر عشرة دقايق\n- متساعد وحبيب جدا ولا عمره رفع صوته\n- تصحيحه كان كويس , دايما فوق ما اتوقع ويخليك تشيك بنفسك من السلوشن\n- غير متفهم في تغيير وقت ميجر حتى لو عندك ميجيرين *ما صارتلي*\n- المادة بشكل عام اسهل من اللي قبلها وواضحة اكثر\n- افهم من الكتاب بعدين حل اسئلة السيلابس حقت البراكتس *نفسها اللي بتحلوها مع الدكتور ونفسها اللي بالميجر*\n- الدكتور يزودك في القريد النهائي رغم انو احيانا ينقال عنو غير كذا بس ما قصر الله يسعده\n- اخيرا انصح به", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1420647", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-haider-husain-madani/98443/18", "user": "Practice", "ts": 1421685993000, "tid": 98443, "pn": 18}}, {"id": "stk-dr-mirghani", "n": "Dr. Mirghani Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "نزلت معاه ACCT210 بترم 133 حضرت كلاسين وحذفت الصيف\n\nالدكتور طيب ويحب ينكت ويهرج مع الطلاب خارج الدراسة\n\nيا ويلك ما تجيب الكتاب 😦 جد يا ويلك , بيحشرلك وينشبلك كذا يقعد واقف جنبك يسألك ليه ما جبت ليه ما جبت\n\nكريم جدا بالتصحيح فوق ما تتصور *كلام واحد اعرفو كمل المادة معاه* , يعني شخبط اي شي تجيب 10 من 15 في الكويز , وغير كذا كريم جدا في القريد النهائي ويدف كثير\n\nشرحه انا اعطيه +B *احسن شرح اكاونتنق مر عليا*\n\nجو كلاسه بشكل عام شغل ويسأل والطلاب يجاوبو مو زي مدني يقعد يقرأ من السلايدات وخلاص\n\nالدكتور كويس في كل شي حتى مياجره سهلة Straight Forward لكن لو عصب الله يعينك عليه\n\nنقطة اخيرة : لو حسيت انه عصب او شي , روحله الاوفيس قوله بجيب الكتاب الكلاس الجاي واعتذر منه بتشوفه يبتسم لك ولا كأنه قد عصب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1421793", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mirghani-ahmed/98438/12", "user": "Practice", "ts": 1422065419000, "tid": 98438, "pn": 12}}]}', 1421685993000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_182-acct210', 'stk-_182', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-mirghani", "n": "Dr. Mirghani Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT210-181\n\nالتحضير: آخر المحاضرة ينادي على الأسماء, يقبل بالميك أب\nطريقة الشرح: شرائح باوربوينت، ويكتب على السبورة إذا لزم الأمر\nالكويزات: لا يوجد\nالمياجر: موحّدة\nالفاينلات: موحّدة\nالقريد النهائي: +A\nالصوت: صوت واضح ولغة ممتازة، لكن الموطن مؤثر على اللكنة (كأغلب الناس)\nإضافات:\n\n- ينزعج من اللي يستخدم جواله، وكثير ما يفاجئهم بسؤال، لكن بمجرد ما الطالب ينتبه يرجع الدكتور وكأنّ شيئًا لم يكن، الدكتور حبيب لأبعد درجة\n- شرحه واضح ويستقبل أي سؤال وحريص أنه يوصّل المعلومة، ونهاية كل تشابتر يخصص محاضرة لحل تمارين عليه، وهذا جدًّا مفيد لتثبيت المفاهيم\n- قبل المياجر يؤكّد على بعض المسائل والمفاهيم من الكتاب، ركز عليها زين، مو معناها أنها كل الاختبار، لكن قطعًا بيجي منها\n- الدكتور الله يجزاه خير مو حول الإيميل، وقبل ما تروح له مكتبه تأكد أنه بيكون موجود لأن كثير ما يروح اجتماعات أو ارتباطات أخرى\n- إذا ركزت مع الدكتور بالمحاضرة وتدربت على المسائل اللي بيحلها معكم أمورك طيبة إن شاء الله\n\n* بالنسبة لملاحظات الأخ اللي فوق, التأخر في التصحيح حاصل مع جميع أساتذة المحاسبة؛ لأن أسئلة الاختبار تصحيحها ياخذ وقت، وأما أنه ما يرفع درجات الاختبار النهائي فصار يرفعها، في 181 رفعها لنا قبل القريد النهائي.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1506105", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mirghani-ahmed/98438/22", "user": "_182", "ts": 1550254110000, "tid": 98438, "pn": 22}}]}', 1550254110000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-nawafmkz-acct210', 'stk-nawafmkz', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-mirghani", "n": "Dr. Mirghani Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Acct210 - 192\n\nالتحضير : نهاية الكلاس، التأخير ممكن يمشيك وممكن يغيبك\nطريقة الشرح : من سلايدات الكتاب ويكتب أحيانا على السبورة. شرح عادي بنبرة صوت ما تتغير إذا ما بتركز بتمل وتضيع\nالكويزات : كويزين سهلة نفس الهانداوت\nالمياجر: الميجر الأول سهل ونفس نظام مياجر acct110\nالفاينلات : لا يوجد ميجر2 وفاينل (كورونا)، البديل اختبارات من موقع الواجب\nالقريد النهائي: B\nالصوت: جيد وأحيانا هادي\nإضافات : المادة متوسطة ومقدور عليها سيلف ستدي فالدكتور خيار مناسب للي يهمه وقت الكلاس وكويزات وشرح عادي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1525352", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mirghani-ahmed/98438/23", "user": "NawafMKZ", "ts": 1599248770000, "tid": 98438, "pn": 23}}]}', 1599248770000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12012-acct210', 'stk-user12012', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-mirghani", "n": "Dr. Mirghani Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT210 - T201 (دراسة عن بعد)\nالتحضير : آخر الكلاس ينادي على الاسماء واحيانًا ما يحضر اذا شاف العدد كامل او شبه كامل في البلاك بورد .\n\nطريقة الشرح : من سلايدات الكتاب ويمشي سلايد سلايد، حاول تقرا بداية التشابتر من الكتاب قبل الكلاس بتفيدك جدًا؛ لأن الدكتور يبدا في الدرس مباشرة بدون مقدمات توضح لك عن ايش الدرس. غالبًا الدكتور يخلص التشابتر في كلاسين، بعض التشباتر اللي تحتاج شغل يزوّد كلاس ثالث يكون لحل تمارين ومسائل.\n\nالكويزات : بما أن الدراسة كانت عن بعد بشكل كامل = تغير توزيع الدرجات وصار فيه كويزات كثير وعليها نسبة كبيرة من الدرجات قرابة الـ ٣٥٪، بعضها بمسمى كويز والآخر اسايمنتس و وكونسبتشول اسسمنت. جميع الاختبارات كانت على Wiley Plus وجميعها كان اختيار من متعدد (Multiple choices). كان الدكتور يرسل لنا ملف مفيد جدًا فيه اسئلة على التشابتر قبل الكويز حاول تحله بعد ما تنتهي من مذاكرة الكتاب .\n\nالمياجر : بما ان الدراسة كانت عن بعد ما كان فيه مياجر وحل مكانها ميد تيرم وكان كومون فيما اعلم وكان على Wiley Plus، وفي المجمل ركّز على الاسئلة اللي يحددها نهاية التشابتر (Problems & Exercises ) والملفات اللي يرسلها لكل تشابتر، هذا كله بعد ما تنتهي من مذاكرة التشابتر من الكتاب ( لا تعتمد على السلايدات لانها وان كانت مأخوذة من الكتاب الا انها فيها نقص في بعض المواضع وتتسم بصعوبة كونها مختصرة + الكتاب ممتاز جدًا وواضح وسهل)\n\nالفاينلات : نفس الميد تقريبًا، وما كان كومبريهنسف (= اللي اختبرناه في الميد ما دخل في الفاينل).\n\nالقريد النهائي : A\n\nالصوت : واضح واللهجة مكس برتش + سوداني 🤪 ، والدكتور من النوع اللي يسأل بين الحين والآخر عشان يتاكد ان الجميع مركز.\n\nإضافات : الدكتور حبيب ومتعاون وحريص جدًا على مصلحة الطالب وياخذ ويعطي مع الطلاب، وكذلك يسوي هلب سشنز قبل الاختبارات المهمة، أحيانًا يعصب على بعض الطلاب كونهم مب مركزين او مهملين لكن اللي التمسته منه انه ما مايعصب الا حرصًا على الطالب ولمصلحته. أرى الدكتور خيار أول في ACCT210 + تقدر تجيب قريد عالي معه (+A+, A, B ) كون المادة سهلة نسبيًا الدكتور متعاون.\n\n.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527781", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mirghani-ahmed/98438/24", "user": "user12012", "ts": 1610299078000, "tid": 98438, "pn": 24}}]}', 1610299078000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-acct210', 'stk-guest', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-madani", "n": "Dr. Haider Husain Madani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بالضبببط 👍\nأحب أزيد شغله إن الدكتور غير متعاون أبدا أبدا\nأحد الكويزات الموقع كان فيه مشكلة وعيا يشتغل الكويز\nرحت للIT وقالوا لي فعلا كان فيه مشكلة وكلم الدكتور حيدر ورفض يفتح لي الكويز مرة ثانية 😠\n\nالتصحيح ظالم جدا جدا في اسئلة الريتن كنت أطلع وانا أقول الريتن فل مارك لكن أتفاجئ بنص الدرجة 😕\n\nالمشكلة أنه هو والحربي مسيطرين على ال210 من فترة فللاسف ستضطر للدراسة عند احد هلأثنين 😭", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1458332", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-haider-husain-madani/98443/22", "user": "Guest", "ts": 1474453271000, "tid": 98443, "pn": 22}}, {"id": "stk-dr-mirghani", "n": "Dr. Mirghani Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT 210\nTERM 201- ONLINE\n\nالتحضير : يحضر نهاية الكلاس و احايانا ما يحضر\n\nالشرح : يشرح من السلايدات و يحل اسئلة الكتاب\n\nالكويزات : سهلة\n\nايجابيات : الدكتور متساعد مع الطلاب و ينزل ملف قبل الكويز فيه اسئلة تجي في الكويز نسخ لصق\n\nسلبيات : اغلب الكويزات يحطها في الويكند , يسأل الطلاب بشكل عشوائي في الكلاس واللي ما يرد يسجله غياب\n\n* اذا تركز معه وتعطي المادة حقها بترتاح معه\n\nالقريد النهائي : B", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527833", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mirghani-ahmed/98438/25", "user": "Guest", "ts": 1610472153000, "tid": 98438, "pn": 25}}]}', 1474453271000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mlekon-acct210', 'stk-mlekon', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-mirghani", "n": "Dr. Mirghani Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT210-192\n\nالتحضير : يحضر عادة نهاية الكلاس لكن اذا شاف الشباب فلوها يبدأ يحضر في البداية ومتساهل في التحضير ما يدقق على التأخير مره\nطريقة الشرح : سلايدات ويشرح منها بس الصراحة شرحه يجيب النوم\nالكويزات : سهله من الاشياء اللي شرحها\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: NP\nالصوت: جيد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529326", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mirghani-ahmed/98438/26", "user": "MLEKON", "ts": 1617515630000, "tid": 98438, "pn": 26}}]}', 1617515630000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-idk-acct210', 'stk-idk', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-mirghani", "n": "Dr. Mirghani Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "المقرر والترم الدراسي: ACCT210-242\n\nالتحضير:\n\nاغرب دكتور بالتحضير مرا يكون شديد مرا يكون متساهل لكن الي عرفته انه ما يقصر مع الي يضرون بدري والي ما يغيبون بس يعني نظامه غريب مرات يحضر بداية الكلاس ومرات بالنص ومرات بالنهاية مرا شديد من ناحية الحضور\n\nالشرح والتعامل :\n\nشرحه سيء لكن الي يميزه انه يعطيك اسئلة تحلها وتكون كبونص عشان اذا جبت العيد بالكويزات تقدر تعوض لكن شرحه مش ولا بد فالمادة راح تقلب سلف ستدي\n\nأعمال السنة :\n\nالواجبات عن طريق الوايلي ومرا غثيثة على كل تشابتر فيه واجب وتاخذ وقت بالحل\n\nالاختبارات :\n\nبالنسبة للكويزات ماهي سهلة ولا هي صعبة يعني مستواها اسهل من المياجر لكن لازم تكون مذاكر التشابتر كامل لانه كويزاته تغطي الافكار ولكن تقدر تقول مضمونة اذا كنت مذاكر والمشكلة على ترمنا صارت الكويزات وزنها 20 درجة فاي غلطة بسيطة تنقصك شي كبير والمياجر جدا صعبة مب زي الدفعات الي درسو معه مستواها صعب ماهو سهل لازم تكون متدرب زين وفاهم كل شي وفوقها تهتم بالكونسيبت يحب الدكتور اسئلة الكونسيبت بس يعني يمكن بكل ميجر يجيك تقريبا اربع اسئلة كونسيبت عموما الميجر الاول كان شوي لخمة الثاني كان اصعب بشوي الفاينل كان موت لدرجة الافرج حق الفاينل صار 60 كان جدا صعب الفاينل وكثير جابو العيد وكان الوقت ابدا ما يكفي مدري وش الهدف من الفاينل ذا لكن ما اتمنى احد يختبر الفاينل الي اخذناه معاه كان جدا صعب واسئلة غريبة مختلفة عن الي تدربنها عليها وبس\n\nإضافات:\n\nخلك هادي طول الوقت حتى لو كلامك موعاجبه بس سلك له وبتزبط امورك الدكتور مزاجي مرات اخلاقه كويسة معك ومرات لا, حول بقدر الامكان توريه انك مهتم ومتساعد وبس\nالدكتور شايب فلا تلوموه اولد سكول بحت", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1539739", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mirghani-ahmed/98438/27", "user": "idk", "ts": 1749034406260, "tid": 98438, "pn": 27}}]}', 1749034406260, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-blake-acct210', 'stk-blake', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-madani", "n": "Dr. Haider Husain Madani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT 210 - 2012 summer\n\nالتحضير :\nنهاية الكلاس وماينسى\n\nطريقة الشرح :\nيجلس ع الكرسي ويتصفح سلايدات ( قراءة وشوية تعليقات ) ، شرحه مايعجبني شخصيا لأني ما اشوف انه شرح اصلا\nباختصار اشوف شرحه سيئ جدا\n\nالكويزات :\nاون لاين والوقت دايم ما يكفي\n\nالمياجر: متوسطة الصعوبة او صعبة ، ولو تحل الهوموورك الاون لاين وتفهمه بتجيب درجة حلوة\n\nالفاينلات : نفس كلام الميجر بس الفاينل اصعب عادة\n\nالقريد النهائي:\n\nC\n\nالصوت:\nواضح جدا وهادئ\n\nإضافات :\n\nالدكتور اخلاق ماشاء الله ومتعاون جدا ودايم مبتسم ومتفهم وساعدنا كثير في الترم الصيفي الله يسعده\nواشوف عيبه الوحيد ( الشرح ) الي هو اهم شي في اي دكتور .\nيرفعك قريد عن قريدك الحقيقي .\nيسمح بالميك اب - يسامح ع التأخير - عنده نقاط مشاركة للطلاب الي يطلعو يحلو الهوموورك ع السبورة\nدايما كان يطلعنا بدري\nلو كان شرحه ممتاز حيكون دكتور الاحلام", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1254637", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-haider-husain-madani/98443/11", "user": "blake", "ts": 1377158686000, "tid": 98443, "pn": 11}}]}', 1377158686000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-random-acct210', 'stk-random', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-madani", "n": "Dr. Haider Husain Madani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Acct 210 - summer 123\n\nد/ حيدر ،، الله يسعده\n\nساعدنا في الصيف\n\nلكن شرحه رؤوس اقلام فقط\n\nتقييمي للدكتور : B+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1255389", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-haider-husain-madani/98443/12", "user": "Random", "ts": 1377445090000, "tid": 98443, "pn": 12}}]}', 1377445090000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-conan14-acct210', 'stk-conan14', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-madani", "n": "Dr. Haider Husain Madani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "سمستر 132 - Acct 210\n\nالتحضير:\nكل يوم ومستحيل يروح عن باله ،،\n\nوبالنسبة للبونس اللي يقولو عليه الشباب ما شميته مع انه ما عندي ولا غياب !!!!\nشباب كثير قالو إنه يعطي الطلاب كلهم upgrade لكن ما شفنا شيئ دا السمستر !!!\n\nطريقة الشرح:\nمملّة جدَّا ،، سلايدات ورؤوس أقلام وممكن يستخدم السبورة لإشتقاق قانون من قانون أو ما شابه ،،\n\nالكويزات:\n3 كويزات كلها أون لاين وياخذ أفضل 2\n\nالمياجر:\nكومن (كلها ريتن) + حول الـ 12 فقرة MCQ ،، اللي يقهر في الموضوع انه آدمي مسوي فلة وفلته فلة شيبان ،، ومستحيل يسمع لك أي كلمة أو اي طلب بس يسلك لك ،، وأزيدكم من الشعر بيت، ميجر 1 وميجر 2 كان عندي أخطاء حسابية بسيطة مع إني كاتب القانون ومعوض تعويض سليم 100% بس الفاينل أنسر خطأ يعطيني ع الفقرة كآآآآملة 0] !!!!!!!!!!!!!!!!!!!!! ،، يا ناس ايش الظلم دا ؟؟؟ أقله لو كتبت لك الفاينل أنسر بس وبدون أي قانون أو تفصيل، تعطيني فل مارك ع السؤال؟ يقول ايوة، طبعاً !!! وبكل وقآآحة 🙂\n\nالفاينل:\nنفس طريقة المياجر\n\nالصوت:\nواضح ،، + إنجليزي مكاوي ،، عاد كيف لا تسألني 🤪 ،، أتخيّل الموقف انت وبس 😁\n\nالقريد النهائي:\nF وبكل جدارة !!! بس ممكن أرفعه للـ D لأنه مافي دكاترة في التخصص المريض والديبارتمنت الميّت دا وأتوقع يجلس في مكانه وقت مو هيّن !!\n\nإضافات:\nالدكتور ممكن يسحب على أي كلاس بدون ما يقلك وتجي انت وتكتشف انه مافي كلاس 🙂 ،، + كثير السفرات (يقلك رايح conference في أمريكا 🤪 وهوا أصلاً رايح يفل ويتطمن على عياله اللي كلهم هناك 😆)\n+\nهو يا إنه مو فاهم ومدري كيف جاب الدكتوراة !!! أو إنه يدرس كورس ماله رغبة فيه !! تبغا تحتج على درجة أو أي شي، مستحيل يسمع خطواتك وإنك فاهم ،، على قوله إنه الاختبارات تجيه جاهزة من ال producer حق الكتاب وأي شي تتكلم عنه يقلك أنا أمشي بالسلوشن حق الكتاب 🙂 ،،\n\nالزبدة\n(ذاكر وأتعوّد على طريقة حل الكتاب نفسه لأنه بنسبة 90% حتنصدم من التصحيح اذا ما حليت بطريقة الكتاب).", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1368826", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-haider-husain-madani/98443/16", "user": "Conan14", "ts": 1400714691000, "tid": 98443, "pn": 16}}]}', 1400714691000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulla_yahia-acct210', 'stk-abdulla_yahia', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-madani", "n": "Dr. Haider Husain Madani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "د. حيدر مدني ]\n\nACCT 210 - Term 132\n- التحضير : دايماً نهاية كل كلاس ينادي بالأسماء ,\n\n- طريقة الشرح : يشرح على السلايدات - **شرحه جيد جداً **+ يعطي أمثلة من الواقع + أحياناً يستخدم السبورة للتوضيح + يشرح الأشياء الأساسية ,\n\n- الكويزات : 3 كويزات أونلاين يأخذ أحسن 2 ( الوقت ضيق + نفس طريقة الهوموركات ) ,\n\n- المياجر : متدرجة \" بحكم تدرج صعوبة المتيريال \" - ميجر 1 سهل ، و ميجر 2 متوسط ,\n\n- الفاينلات : نفس طريقة المياجر ,\n\n- القريد النهائي : B\n\n- الصوت : واضح و لهجته جيدة ,\n\n- إضافات : الدكتور سهل التعامل و محترم ، + يعطي بونس 1% للي عنده غياب على الأكثر + لكن تصحيحه شديد ,", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1374455", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-haider-husain-madani/98443/17", "user": "Abdulla_Yahia", "ts": 1401452404000, "tid": 98443, "pn": 17}}]}', 1401452404000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_assan-acct210', 'stk-_assan', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-madani", "n": "Dr. Haider Husain Madani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT210 Term 142\n\nالتحضير : بداية الكلاس وأحيانا آخر الكلاس\n\nطريقة الشرح : سلايدات يقراهم ويحاول يخلي الطلاب يشاركون (الشرح 6 من 10)\n\nالكويزات : عطانا كوزين اونلاين , أسئلتهم زي أسئلة الهومورك الاونلاين\n\nالهوموركات : فيه هومورك اونلاين + يخصص كلاس كل اسبوعين حق الهوموركات اللي موجودة في السلبس ويوزعها على الطلاب علشان يحلونها على السبورة (عليها درجات)\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: B\n\nالصوت: واضح\n\nإضافات : المدرس طيب وحبوب ومتعاون لكن مايتعب روحه في الشرح لدرجة إنك ممكن تطلع من الكلاس وباقي نص ساعة! , سوا لنا كم هلب سشن قبل المياجر والفاينل (فيه تحضير وعليهم درجات) , كان مفروض يعطينا ثلاث كوزات لكن عطانا بس اثنين , خذ أحسن درجة منهم وأضاف عليها درجة كوز كاملة , ماكنت أعرف سالفة الدروس إلا قبل المياجر بيومين هههههههه (من طيب الشرح :D)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1424532", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-haider-husain-madani/98443/19", "user": "_assan", "ts": 1439979474000, "tid": 98443, "pn": 19}}]}', 1439979474000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ksa-wolf-acct210', 'stk-ksa-wolf', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-alharbi", "n": "Dr. Abdullah D. Alharbi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT 210 - Term 142\n\nبنود التقييم :\n\nالتحضير :\n\nيحضّر كل كلاس في بدايته…\nطريقة الشرح :\n\nجالس على الكرسي و يمر على السلايدات و يشرحها… شرحة تفهم منه لو قارئ الدرس من قبل… المادة في النهاية Self Study لا تعتمد على الدكاتره كلهم شرحهم لك عليه… ممكن تسأله و يهزأك على سؤالك ، فإذا تنحرج روح له في الأوفس و لا سوي مثل طالب أعرفه كان يروح للدكتور مرغني من ACCT 110 إنسان طيب و يفهمك…\nالكويزات :\n\nفيه كوزين أون لاين…\nالمياجر:\n\nكومن… الأول كان عليه 25% و الثاني 30%… إذا كان 10 من 10 هو أعلى مستوى في الصعوبة… فالأسئلة تتراوح من 5-8 من عشرة… تجي من الأون لاين هوموورك و (السجستد هوموورك أو البروبليمز) الموجودة في السلابس ممكن تجي من الكتاب… لكن ركز على الأون لاين هوموورك و الأسئلة في السيلابس\nالفاينلات :\n\nكومن نفس المياجر… على الفاينال 30%\nالقريد النهائي:\n\nC\nالصوت:\n\nواضح\nإضافات :\n1-بالنسبة للوقت المحدد للكوز أنتبه لا تمشي على كلامه… قالنا في الكوزين كلهم أنهم ساعتين و طلعوا 50 دقيقة و بعدين يقفلوا… الكوزات ذاكر لها زين. لأنها مثل الميجر و المشكلة بالوقت جدا جدا قصير…\n2- مع الدكتور بيكون فيه حصة قبل الميجر للمراجعة… ركز فيها و شوف المواضيع اللي بيتكلم عنها… مليون في المئة بيجيك منها في الميجر.\n3- جيب الكتاب و الحاسبة معك… لأنه بينقص عليك لو ما جبتهم… كان يقول في كل حصة و يقعد يكررها حتى حفظتها… Bring a pin or a pencil and the book and a calculator. أنا مره ما جبتها فهزأني و حط خطأ عند اسمي و لكن ما نقص علي لأني أخذت في الدرجة النهائية 5 من 5 في المشاركة 😛\n4- المادة سهلة، أسهل من 110 بكثير و لكن تصحيح الدكتور حيدر ظالم شوي… مره كان الجواب النهائي لطالب خطأ لأنه زاد رقم فقط و عطاه صفر في ذاك الجزء من المسألة… و قال لو جبت الجواب النهائي صحيح بعطيك الدرجه كاملة. (الإختبارات كلها تروح للدكتور حيدر… هو المصحح). و شيء ثاني الأسئلة محددة (قليلة) في المياجر و الفاينال… في الفاينال جانا 3 بروبلمز و 15 أسئلة اختياري. و المياجر مثلها… تضيع سؤال تخسر درجات كثير…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdullah-d-alharbi/98423/17", "user": "KSA-WOLF", "ts": 1451383389000, "tid": 98423, "pn": 17}}, {"id": "stk-dr-madani", "n": "Dr. Haider Husain Madani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT 210 - Term 151\n\nبنود التقييم :\n\nالتحضير :\n\nيحضّر كل كلاس في بدايته غالبا… و ما شاء الله يحفظ الطلاب من ثاني أسبوع… هو اللي يحضر بنفسه…\n\nطريقة الشرح :\n\nما يشرح كويس… الدكتور طيب و أخلاق لكنه ما يعرف يوصل المعلومة… يمر على السلايدات و يعلق عليها.\nو\nإذا تبغى تفهم معاه لازم تكون محضر الدرس قبل ما تجي… بتستفيد من الكلاس لو محضر الدرس…\nالكويزات :\n\nفيه ثلاث كوزات أون لاين معه بيأخذ أحسن 2 منهم… واحد قبل الميجر الأول و واحد قبل الثاني و واحد قبل الفاينال\n\nالمياجر:\n\nكومن… الأول كان عليه 25% و الثاني 30%… من متوسط لقليل الصعوبة.\n\nالفاينلات :\n\nكومن نفس المياجر… على الفاينال 30%\n\nالقريد النهائي:\n\nd+\nالصوت:\n\nواضح\n\nإضافات :\n1-الكوزات أوقاتها قليل جدا… يعني لو تحتاج للكوز ساعتين بيعطيك هو 50 دقيقة… فذاكر لها زين…\n2- مع الدكتور حيدر فيه درجات المشاركة و هي 5%… جمعها كلها أو ما راح يمديك تأخذ الخمسة… تجمعها من خلال المشاركة في حل الهومووركات اللي في السلابس… بعد كل شبترين أو ثلاث بيختار طلاب عشان يطلعوا و يحلوا الأسئلة اللي في السيلابس في الكلاس اللي بعده على السبورة… كل مره تطلع ب 1%… فجمعها كلها من بدري ولا ما بيمديك تأخذها كلها… لأنه على ما أذكر المرات المتاحة لك هي 6 أو 7 مرات خلال الترم. و إذا ما اختارك عشان تحل… برضوا ذاكر الأسئلة و روح محضر لأنه في حال غياب طالب من اللي بيحلون الأسئلة بيختار هو طالب من الكلاس يجي محله… فخليك محضر عشان تطلع. و شي كمان لا تنقل الحل من السلوشن على السبورة لأنه بيسألك كيف حليتها و كيف جت كذا و ليش استخدمت القانون هذا…\n3- المادة سهلة، أسهل من 110 بكثير و لكن تصحيح الدكتور حيدر ظالم شوي… مره كان الجواب النهائي لطالب خطأ لأنه زاد رقم فقط و عطاه صفر في ذاك الجزء من المسألة… و قال لو جبت الجواب النهائي صحيح بعطيك الدرجه كاملة. (الإختبارات كلها تروح للدكتور حيدر… هو المصحح). و شيء ثاني الأسئلة محددة (قليلة) في المياجر و الفاينال… في الفاينال جانا 3 بروبلمز و 15 أسئلة اختياري. و المياجر مثلها… تضيع سؤال تخسر درجات كثير…\n4- لا تغيب ولا كلاس لأن اللي ما يغيب له بونص 1% مع الدكتور حيدر فقط .\n\nدمتم بحفظ الله\n🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437313", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-haider-husain-madani/98443/20", "user": "KSA-WOLF", "ts": 1451385521000, "tid": 98443, "pn": 20}}]}', 1451383389000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abu_taki-acct210', 'stk-abu_taki', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-madani", "n": "Dr. Haider Husain Madani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT 210\nTerm 152\n\nالتحضير : بداية الترم كان يحضر مع بداية الكلاس وبعدها صار يحضر في نهاية الكلاس وما ينسى ابداً\n\nطريقة الشرح : يجلس على الكرسي ويتصفح السلايدات ويعلق عليها … ويشرح على السبورة الأشياء اللي تحتاج شرح\n\nالكويزات : 3 كويزات اونلاين رح يأخذ احسن 2 منها … الكويزات طويلة ووقتها قصير وهي عبارة عن حل مسائل شبيهة للي في نهاية كل شابتر وهي شبيهة أيضا للي تجي في الميجر\n\nالمياجر: المياجر متوسطة الصعوبة ولازم تفهم فكرتها وكيف تستعد لها … المسائل غالبا تجي نفس المسائل اللي في السيلبس مع تغيير الأرقام + الجزء الاخر الملتبل شويس وهي أيضا شبيهة باسئلة الملتبل شويس في نهاية كل شابتر واحيانا تجي نسخ لصق\nالفاينلات : نفس الكلام بالنسبة للمياجر\n\nالقريد النهائي: B+\nالصوت: واضح ولغة انجليزية جيدة\nإضافات : الدكتور حيدر خلوق ومحترم جداً مع الطلاب … شرحه جيد الى حد ما ولكن بعد فترة من السمستر ممكن يصير الكلاس ممل بالنسبة لك … عموماً الكورس سهل اذا عرفت تتعامل معاه … الدكتور يزيدك درجة واحدة عن مجموعك اذا عندك غياب واحد او اقل\n\nخليه خيارك الأول في ACCT 210", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1457095", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-haider-husain-madani/98443/21", "user": "Abu_Taki", "ts": 1473204009000, "tid": 98443, "pn": 21}}]}', 1473204009000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9840-acct210', 'stk-user9840', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-madani", "n": "Dr. Haider Husain Madani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT 210-Term 162\n\nالتحضير : يحضر نهاية كل كلاس\nطريقة الشرح : ههههه مايشرح يفرفر السلايدات وبس لدرجة ان متيريل الفاينل ماشرحه هو مخلي الطلاب يشرحون ويعطيهم درجتين !!!!!\nالكويزات : كويزين اونلاين\nالمياجر: سهلة لكن صعوبتها تكمن في تصحيحه المعاق\nالفاينلات : نفس المياجر\nالقريد النهائي: D ويخب عليه\nالصوت: واضح والاكسنت منتاز\nإضافات :\nمدني فله في الكلاس وكان خويي في الكلاس واقط عليه ويقط علي 🙂 لكن في الشرح من جنبها .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1475971", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-haider-husain-madani/98443/25", "user": "user9840", "ts": 1499304362000, "tid": 98443, "pn": 25}}]}', 1499304362000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10207-acct210', 'stk-user10207', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-alharbi", "n": "Dr. Abdullah D. Alharbi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT 210 - Term 142\n- التحضير: أحياناً يحضر وأحياناً لا. التحضير يكون بداية الكلاس.\n- الشرح: عادي جداً. يشرح شرح سريع من السلايدات ونادراً مايكتب على السبورة.\n- يشرح أشياء اساسية وبسيطة ومايدخل بالتفاصيل.\n- الدكتور أشوفه مهمل. مايهتم أبداً للمادة ولا للطلاب.\n- مايعطي كويزات أبد طول السمستر. لكن مرة سافر وعطانا ظ¢ كويز أونلاين.\n- أيضاً مايعطي هوموركات. وإن عطا هومورك مايصححه ويخليه عندك.\n- المياجر والفاينل يسويها الدكتور مدني.\n- كل شيء يسويه الدكتور مدني من مياجر وهومورك وكويزات حتى الدرجات والقريدات.\n- فلذلك أنصح الطلاب يدرسون عند مدني لأنه هو الي يحط الأسئلة ويقولهم وش الي بيجي.\n- من الكويزين الي عطانا يأخذ أفضل درجة.\n- قبل الميجر والفاينل فيه كلاسات في الليل مراجعة عليها بونص الحضور.\n- بعض الكلاسات مايطول. يطلع الطلاب قبلها بنصف ساعة.\n- يستخدم البلاكبورد ويتواصل بالإيميل.\n- تصحيحه للمياجر أشوفه جيد.\n- لغته الإنجليزية جيدة. ممنوع تتكلم عربي في الكلاس.\n- يتجاوب مع اسئلة الطلاب في الكلاس. بعض الأحيان تعامله سيء.\n- مايحب أحد يستخدم الجوال في الكلاس. جداً يترفز.\n- المادة فيها مسائل أكثر من أنها نظرية، فعشان كذا أسلوب الدكتور مايصلح أنه يشرح بسرعة من سلايدات.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1423046", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdullah-d-alharbi/98423/13", "user": "user10207", "ts": 1438031253000, "tid": 98423, "pn": 13}}]}', 1438031253000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mkt.abdullah-acct210', 'stk-mkt.abdullah', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-alharbi", "n": "Dr. Abdullah D. Alharbi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT 210 - Term132\n\nالتحضير :\n\nيحضّر كل يوم , ويتنرفز من المتأخرين .\n\nطريقة الشرح :\n\nشرحه ممتاز بالنسبة لي , يتكلم عن الموضوع ويعطي امثلة من الواقع ويحل مسائل على السبورة .\n\nالكويزات :\n\nما اذكر انه اعطانا كويزات.\n\nالمياجر:\n\nيسوي كلاس مراجعة قبل المياجر , وكان مفيد جداً , لأنه ركز على افكار جاتنا في الميجر.\n\nالفاينلات :\n\nكومون\n\nالقريد النهائي:\n\nاعطيه B+\n\nالصوت:\n\nواضح وجهوري , بس لغته الانجليزية لك عليها شوي .\n\nإضافات :\n\nالدكتور لسانه متبري منه شوي . ومرات يشطح الله يهديه , بس اذا كنت ماشي معاه تمام صدقني ما راح تلقى الا كل خير.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1425467", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdullah-d-alharbi/98423/14", "user": "MKT.Abdullah", "ts": 1440431283000, "tid": 98423, "pn": 14}}]}', 1440431283000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr.sir-acct210', 'stk-mr.sir', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-alharbi", "n": "Dr. Abdullah D. Alharbi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أتفق مع الكلام إلي فوق وأحب أضيف الدكتور من ناحية شرح ماعنده سالفة صراحة يبذل أقل جهد وكل اعتماده ع السلايدات وحتى السلايدات ما يراجعها قبل مايجي للمحاضره دايم يتفشل يقول جواب ثم يكمل السلايد ويطلع جوابه غلط ناهيك عن اسلوبه مستفز واعتقد الناس الحساسه ماتتحمله هو من النوع الي خذه ع قد عقله دايم يجيب العيد بس محد يدقق واحس انه من الدكاتره الي يهدد ومدري كيف واخر الترم يطلع طيب ويساعد كثير …يعني ياليت لو ياخذ مهمته بالتدريس بجدية أكبر ويحلل الراتب إلي ياخذه بدل مايدور راحته ويبذل minimum effort", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1443183", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdullah-d-alharbi/98423/18", "user": "MR.Sir", "ts": 1456468957000, "tid": 98423, "pn": 18}}]}', 1456468957000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hussain_hd-acct210', 'stk-hussain_hd', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-amr", "n": "Dr. M. Amr", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT210 - T191\n\nالتحضير: يوميا على ورقة، لكنه مايحب المتأخرين ويعتبرهم مو مهتمين\n\nطريقة الشرح: سلايدات وشرييييح اخر درجة بطل بطل في الشرح توب التوب بس ركز معه، يستعمل الكتاب بعض الاحيان حتى يشرح جزئية نظرية\n\nالكويزات: تقريبا ٣-٤ كويزات وتعتبر سهلة يمكن بس واحد أو اثنين اللي جاب فيهم ترك بسيط\n\nالمياجر: كومن\n\nالفاينلات: كومن\n\nالصوت: واضح وعالي\n\nالقريد النهائي: A+\n\nإضافات: الدكتور عمر ممتاز جدا بالشرح لكن لابد تبين له انك مهتم خلال الكلاس، الاوفس اورز حقه ماهو مرة عاطيها اهتمام بس يغنيك بالكلاس، انصح فيه للي ما يتأخرون", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1519718", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-amr/98439/40", "user": "Hussain_HD", "ts": 1580825285000, "tid": 98439, "pn": 40}}]}', 1580825285000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-fhd-acct210', 'stk-fhd', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-amr", "n": "Dr. M. Amr", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT210 - 192\n\nالتحضير: يوميا على ورقة.\n\nطريقة الشرح: سلايدات.\n\nالكويزات: قريبه من الهاند اوت اللي يوزعه دايم بعد كل تشابتر.\n\nالمياجر: كومن\n\nالفاينلات: كومن\n\nالصوت: عالي جدا\n\nالقريد النهائي: B\n\nإضافات: الدكتور متساعد معنا … صوته وهو يشرح ممكن يزعج البعض.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1522550", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-amr/98439/41", "user": "FHD", "ts": 1591092990000, "tid": 98439, "pn": 41}}]}', 1591092990000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sadguts-acct210', 'stk-sadguts', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-alhazmi", "n": "Dr. Muhammad Alhazmi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Acct210-201\nالتحضير : بدايه كل كلاس ويحضر المتأخرين ف النهايه ويحط ليت\nالشرح: والله الدكتور اخلاقه طيبه ومسكين لكن الصدق ماله ف الشغله خلاص كبر في السن وصار يقرا السلايدات بس ويمشي مايحل تمارين ولا شيء يقرا الحلول بس. اتفق مع تعليق “توحيد” فوق ☝️\nالكويزات: الصدق انه لعب فينا كان يجيب المتيريل المحذوف من الكوردنيتر ويحطه ف الكويزات واذا قلنا له ليش يقول عشان يصير عندكم knowledge اكثر من السكاشن الثانيه!\nاضافات: الدكتور مسكين وطيب جدا لكن مانصح اي احد ينزل عنده والله شرحه تعبان واختباراته مدري شوضعها اخذت A+ لكن كنت احضر محاضرات الدكتور عمرو الاسطوره (فايده الاونلاين الوحيده) واذاكر من الكتاب + الهانداوت واتمرن عالاوريون ف وايلي بلس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527857", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-muhammad-alhazmi/98415/11", "user": "SadGuts", "ts": 1610565675000, "tid": 98415, "pn": 11}}]}', 1610565675000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-maxmx05-acct210', 'stk-maxmx05', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-nainar", "n": "Dr. S M Khalid Nainar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "TERM 171\nACCT 210\nالاسبوع رقم 9\nالتحضير : ابد مع بداية الكلاس يبدا يحضر. يسمح بالتاخير الى 10 دقايق\nطريقة الشرح : سلايدات ويحل مسائل حسابية بسيطة على السبورة\nالكويزات : كومن\nالمياجر: كومن\nالفاينلات :كومن\nالقريد النهائي: A\nالصوت:واضح\nإضافات :\nراح اتكلم عن الشيء المهم\n\nالتصحيح: بما ان 85% مياجر و حدود 55-60 % منها رتن ف التصحيح مهم جدا\n\nتصحيح الدكتور ممتاز جدا يمشي لك اهم شيء اكتب شيء", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1483292", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-m-khalid-nainar/177580/2", "user": "Maxmx05", "ts": 1510500462000, "tid": 177580, "pn": 2}}]}', 1510500462000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10407-acct210', 'stk-user10407', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-nainar", "n": "Dr. S M Khalid Nainar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "171-ACCT210\nالتحضير : بداية كل كلاس ، ينادي على الاسماء\nطريقة الشرح : من السلايدات و بشكل جيد\nالكويزات : كومن اونلاين\nالمياجر: كومن - ( كانت من الكوردنيتر عبدالله الحربي ) سهلة\nالفاينلات : نفس المياجر\nالقريد النهائي: B\nالصوت: واضح\nإضافات : تصحيحه ممتاز جدا و الدكتور طيب ، يسوي كل فترة كلاس اضافي يحل فيه أسئلة الكتاب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485602", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-m-khalid-nainar/177580/3", "user": "user10407", "ts": 1515265317000, "tid": 177580, "pn": 3}}]}', 1515265317000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-jafar_15-acct210', 'stk-jafar_15', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-nainar", "n": "Dr. S M Khalid Nainar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT 210 -171\n\nالتحضير : بداية كل كلاس بالسريال نمبر\n\nطريقة الشرح : يشغل السلايدات ويجلس يتكلم، اذا في معادلة او نقطة مهمة يستخدم السبورة ويشرحها. بالنسبة لي طريقة شرحه مملة جدا جدا وتجيب النوم.\n\nالكويزات : اونلاين وتكون نفس الواجبات\n\nالمياجر: كومن، متوسطة الى سهلة لكن يعيبها عدد الاسئلة قليلة والسؤال الواحد عليه درجة مرتفعة نسبيا خصوصا لو تقارنه بمياجر 110.\n\nالفاينلات : كومن، ونفس نظام المياجر\n\nالصوت: نص واضح ويجيب النوم\n\nإضافات : تصحيح الدكتور خرافي خرافي، حتى لو حلك غلط يعطيك عليه بوينت اهم شي تكتب اي شي. المادة تقدر تعتبرها سلف ستدي والكتاب واضح، والسلايدات بشكل عام واضحة وتغنيك عن الكتاب. بشكل عام كنت احضر للدكتور حضور شرف بس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485841", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-m-khalid-nainar/177580/5", "user": "Jafar_15", "ts": 1515517226000, "tid": 177580, "pn": 5}}]}', 1515517226000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ky_95-acct210', 'stk-ky_95', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-nainar", "n": "Dr. S M Khalid Nainar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "طبعا اول شي انا اخذت عنده ACCT 210-171\nالتحضير : التحضير يحضر بداية كل كلاس ب السيريال نمبر حقك\nطريقة الشرح : الدكتور للامانه بالنسبة لي عيبه الوحيد انه شرحه ممل جداااااااا، هو صراحة ما يقصر معاك، بداية كل كلاس يراجعلك الاشياء اللي شرحها في التشابتر وبعدها يشرح الجديد ويحاول يربطلك الدروس ب أمثلة من الواقع عشان يفهمك ومتعاون جدا بالاسئلة حتى انه يسوي كلاس نهاية الاسبوع يحل عليه تمارين وأسئلة ويسوي لك مراجعة قبل الميجر يغطيلك كل المفاهيم. بس زي ما قلت شرحه ممل بس انك تقدر تعتمد ع الكتاب والسلايدات او حتى باليوتيوب وتطلع ب قريد حلو\nالكويزات : كومن من البلاكبورد وكانت سهلة\nالمياجر: كومن وكانت سهلة\nالفاينلات : نفس طريقة المياجر وسهله بعد بس الاثنين مشكلتهم انه عدد الاسئلة قصير يعني لو تجيب العيد ب سؤال ب تطير عليك درجة كبيرة\nالقريد النهائي: للامانة الدكتور اعطيه A+ ويستاهل اكثر منها بعد\nالصوت: واضح\nإضافات : ايجابيات الدكتور تغطي ع سلبيته الوحيدة اللي هي شرحه الممل ولكن صدقني بتخلص عنده السمستر واول ما تشوف القريد حقك والله بتحبه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1487601", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-m-khalid-nainar/177580/6", "user": "ky_95", "ts": 1518290312000, "tid": 177580, "pn": 6}}]}', 1518290312000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-makkahboy-acct210', 'stk-makkahboy', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-nainar", "n": "Dr. S M Khalid Nainar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT210 - 172\n\nالتحضير: يحضر في بداية الكلاس بالسيريال نمبر\n\nطريقة الشرح: يشرح من السلايدات ويحل أسئلةكومبريهنسف (شاملة) قبل المياجر ويفهههمك مزبوط الله يعطيه العافية\n\nالكويزات : أونلاين كومن (نفس طريقة الهوموركات) قبل المياجر (2) وقبل الفاينل (1) وعليها كلها 10%. دكتور خالد اذكر حذف أسوء وحدة\n\nالمياجر: كومن ،سهلة، القسم ماشاء الله سهلو لنا المياجر كلها والفاينل.\n\nالفاينل: كومن وسهلة\n\nالتصحيح: متساهل في التصحيح ويدفك لو رحت له المكتب\n\nالصوت: صوته جيد بس إذا كنت ورا بالأخير فممكن ماتسمع لكن بالمجمل صوته طيب.\n\nإضافات:\n- التحضير عنده متساهل جدا ولو تتأخر وتجي بالأخير يحضرك قبل نهاية الكلاس، يقبل الميك آب أو أنك تحضر في سكشن آخر ومرن جدا\n(اذكر كنا نخلص بعض الأحيان كلاس مادة ثانية بدري ونروح له على طول على كلاسه ويكون بقى نص ساعة أو 20 دقيقة أو حتى ربع ساعة ويحضرنا)\n- الدكتور متعاون مع الطلاب ويعلمك ماينفعك عموما في الحياة ويبا مصلحتك\n- صراحة المادة يمدي تذاكرها من الكتاب وتفهم (سهلة) (فيه شباتر ماحضرتها أصلا معه وذاكرتها قراءة من الكتاب وفهمتها فهم كووويييس وخرجت بقريد عالي جدا)\n- لو تذاكر من الكتاب وتحل الأسئلة (حلول الكتاب تقدر تلقاها عند الشباب) … وضعك في السليييييم\n\nالقريد النهائي: A+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1493675", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-m-khalid-nainar/177580/7", "user": "makkahboy", "ts": 1528083908000, "tid": 177580, "pn": 7}}]}', 1528083908000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-9ami-acct210', 'stk-9ami', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-mirghani", "n": "Dr. Mirghani Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ميرغني 🙂\n\nالشرح واضح ومفهوم … مستوى الكويزات من متوسط إلى سهل\n\nبينما حيدر مدني شرح جيد لكن الكويزات تتميز بصعوبتها\n\nلذلك أنا أقولك توكل على الله ونزل المادة مع ميرغني .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1025583", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/124547/2", "user": "9ami", "ts": 1334937269000, "tid": 124547, "pn": 2}}]}', 1334937269000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sooonah-acct210', 'stk-sooonah', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-mirghani", "n": "Dr. Mirghani Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "كوزات سهله\nما يدقق في التحضير\nتصحيح ولا احلى\nعنده بووونص للي ما يغيب واللي يحل بعض الاسئله اللي يعطيك اياها في الكلاس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1026149", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/124547/6", "user": "sooonah", "ts": 1335017923000, "tid": 124547, "pn": 6}}]}', 1335017923000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user3328-acct210', 'stk-user3328', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-mirghani", "n": "Dr. Mirghani Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "كورس acct202 - ترم 083\nكورس acct401 - ترم 091\n\nالتحضير\nآخر المحاضره ولا عنده أي مشكله في التأخير الا نادرا\n\nطريقة الشرح\nمتوسطه … يشرح على السلايدات واذا فيه مسائل حلها على السبوره\nفي بعض الأحيان اذا استصعب الفهم على أحد الطلاب يشرح له بالعربي\n\nالكويزات\nكل كوزاته تكون مسائل وسؤال واحد يا إما تعريف أو عدد وعلل … المسائل تافهه وتكون نفس اللي حلها قبل بالكلاس\n\nالمياجر\nمياجره دسمه جدا جدا جدا … تعتمد بشكل كبير على فهمك للماده ومدى تمرينك على حل المسائل …\nفي المقابل … متعاون جدا بالتصحيح ولو تجيب له طرف الحل في الأسئلة المقاليه عطاك الدرجه\nبشكل عام … اذا انت منت لعاب وتحضر وتفهم واذا جا وقت المياجر حليت كم مسأله وحفظت التعاريف وغيرها … راح تجيب درجه عاليه … لأن المسائل يكون عليها تقريبا 75% من الدرجه\n\nالفاينلات\nنفس الكلام اللي على المياجر\n\nالقريد النهائي\nB+ … الدكتور يدف بالقريدات ويحاول يساعد الطلاب قدر استطاعته\n\nالصوت\nجيد … وانجليزيته حلوه لكن صعوبة الفهم بسبب لكنته …\n\nإضافات\nحاليا برأيي هو الأفضل لـ202 … مثل ماسبقني اخوي فوق … الدكتور تمسك معه احيانا يعامل الطلاب كأنهم أطفال وانتبه لا يحطك براسه انك لعاب … ولو تخليه يعرفك زين ماراح تخسر وبالعكس راح يتذكرك وقت الدرجات …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p790051", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mirghani-ahmed/98438/4", "user": "user3328", "ts": 1297700295000, "tid": 98438, "pn": 4}}]}', 1297700295000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-the-financial-acct210', 'stk-the-financial', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-mirghani", "n": "Dr. Mirghani Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور احمد نمر ميرغني دكتور درجة اولى ممتاز فاهم مرة انا اخذت معاه 202 زمان قبل سنتين\n\nيهتم بالواجبات زي ماقال الاخ ابو العدن اسئلته اللي اذكره انو الاختبار الاول كان كله اختيارات والاختبار الثاني كان كله مسائل حسابية واسئلة مقالية بس بالنسبة لي تصحيحة في الاختبار الثاني ممتاز على الاقل يصحح على مدى فهمك افضل من الاختيارااات عندو طريقة مرة ممتازة\nاذا اخذت بالاختبار الاول والثاني ممتاز والاختبار النهائي يعني فوق المعدل تاكد انك راح تاخذ A والاختيار لك حاجة مهمة يهتم بكلاس الاب يحل اسئلة فيه وراح يخليكم تحلون معاه والخيار لك\n\nوبالتوفيق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p174075", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct202-in-the-summer/56719/4", "user": "The-FiNaNcial", "ts": 1181314721000, "tid": 56719, "pn": 4}}]}', 1181314721000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5374-acct210', 'stk-user5374', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-madani", "n": "Dr. Haider Husain Madani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اخذت معه Acct 202\nممتاز في كل شيء …\nالمياجر سهلة وواضحة جداً ، الكويزات فيها تريكات 🙂\nبعد اول ميجر ، بتعرف كيف طريقته في الأسئلة و تعرف وش المسائل اللي لازم يجيبها في الميجر الثاني والفاينل 🙂\nهالكلام بعد ما نزلت المادة بالصيف و الأسئلة منه فقط …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1119107", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-haider-husain-madani/98443/10", "user": "user5374", "ts": 1353186976000, "tid": 98443, "pn": 10}}]}', 1353186976000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-s.a.l.m.a.n-acct210', 'stk-s.a.l.m.a.n', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-kurdi", "n": "Dr. Ammr Kurdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده acct202\n\nالتحضير :\nيوميا في اول المحاضره\n\nطريقة الشرح :\nالدكتور شرحه جدا جدا ممتاز , طبعا عن طريق سلايدات وحل تمارين على السبوره\n\nالكويزات :\nيوم كنت آخذها كان مافيه كويزات بس كان فيه سيكشن ميجر وكل دكتور يسويه لكلاسه , متوسط\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nاعطيه a\n\nالصوت:\nواضح والاكسنت ممتازه\n\nإضافات :\nالرجل اخلاق و محترم , من خريجين البترول وفاهم الطلاب\nعيبه الوحيد ان الهومووركات طويله جدا\nيوم كنت آخذها ما كان فيه كويزات فما كنت اذاكر الماتيريال الا قبل المياجر , لكن مجرد انك تركز معاه في الكلاس تحس انك تفهم ويبين الفهم لما تحل الهوموورك\n\nانا تخصصي مو اكاونتينج , وخلصت كورسات الاكاونتينج , لكن لو باخذ كورس ثاني في المحاسبه فراح اسجل عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1058042", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-ammr-kurdi/99892/10", "user": "S.a.l.m.a.n", "ts": 1340270358000, "tid": 99892, "pn": 10}}]}', 1340270358000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-google2007-acct210', 'stk-google2007', 'ACCT 210', 'doc', '{"docs": [{"id": "stk-dr-kurdi", "n": "Dr. Ammr Kurdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا حاليا ماخذ معاه acct 202\n\nالدكتور قمة في الاخلاق والتعامل وعليه اسلوب جبار في الشرح يخليك تستمتع بالمادة (مع انها مو تخصصي) ويتقبل الاسئلة بشكل رحب ويحرص ان جميع الطلاب يفهمون المادة , الصراحة من فترة ما حصلت دكتور مثله.\n\nبالنسبة للكويزات متوسطة الى سهلة والمياجر كومن بس شديد جدا في التحضير والتأخر ويبدأ يحضر من اول دقيقة.\n\nنزل معاه وانت مغمض", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p751312", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/99531/3", "user": "google2007", "ts": 1293240596000, "tid": 99531, "pn": 3}}]}', 1293240596000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
